-- Bounded PostgreSQL vertical-slice schema. Execute only in a disposable test DB.
-- No production endpoint, migration, or application runtime selection is encoded here.
create table if not exists slice_user (id bigint generated by default as identity primary key, username text unique not null, password_hash text not null, active boolean not null);
create table if not exists slice_permission (id text primary key, parent_id text references slice_permission(id), name text not null);
create table if not exists slice_personnel (id bigint generated by default as identity primary key, name text not null, department text not null);
create table if not exists slice_equipment (id bigint generated by default as identity primary key, name text not null, status text not null);
create table if not exists slice_consumable (id bigint generated by default as identity primary key, code text unique not null, quantity numeric not null);
create table if not exists slice_report (department text primary key, record_count bigint not null);
